void avl_insertar(AVL *raiz, int x) {
    if (raiz == NULL) {
        return;
    }

    AVL padre = NULL, actual = *raiz;
    while (actual != NULL) {
        padre = actual;
        if (x < actual->nro) 
            actual = actual->izq;
        else if (x > actual->nro) 
            actual = actual->der;
        else 
            return; // no duplicados
    }

    AVL nuevo = malloc(sizeof(*nuevo));
    if (nuevo == NULL) {
        return;
    }
    nuevo->nro = x;
    nuevo->FE = 0;
    nuevo->izq = nuevo->der = NULL;
    nuevo->padre = padre;

    if (padre == NULL) {
        *raiz = nuevo;
        return;
    }
    if (x < padre->nro) 
        padre->izq = nuevo;
    else 
        padre->der = nuevo;

    // Rebalanceo incremental tras inserción
    AVL n = nuevo;
    while (padre != NULL) {
        if (n == padre->izq) 
            padre->FE--;
        else 
            padre->FE++;

        if (padre->FE == 0) 
            break;
        if (padre->FE == -2) {
            if (n->FE <= 0) 
                avl_RSD(raiz, padre);
            else 
                avl_RDD(raiz, padre);
            break;
        }
        if (padre->FE == 2) {
            if (n->FE >= 0) 
                avl_RSI(raiz, padre);
            else 
                avl_RDI(raiz, padre);
            break;
        }
        n = padre;
        padre = padre->padre;
    }
}

void avl_RSD(AVL *r, AVL nodo) {
    if (r == NULL || nodo == NULL || nodo->izq == NULL) {
        return;
    }

    AVL padre = nodo->padre;
    AVL A = nodo;
    AVL B = A->izq;
    AVL C = B->der;

    if (padre) {
        if (padre->der == A) 
            padre->der = B;
        else 
            padre->izq = B;
    } 
    else {
        *r = B;
    }
    A->izq = C;
    B->der = A;
    A->padre = B;
    if (C) 
        C->padre = A;
    B->padre = padre;

    A->FE = A->FE + 1 - (B->FE < 0 ? B->FE : 0);
    B->FE = B->FE + 1 + (A->FE > 0 ? A->FE : 0);
}

void avl_RSI(AVL *r, AVL nodo) {
    if (r == NULL || nodo == NULL || nodo->der == NULL) {
        return;
    }

    AVL padre = nodo->padre;
    AVL A = nodo;
    AVL B = A->der;
    AVL C = B->izq;

    if (padre) {
        if (padre->der == A) 
            padre->der = B;
        else 
            padre->izq = B;
    } 
    else {
        *r = B;
    }
    A->der = C;
    B->izq = A;
    A->padre = B;
    if (C) 
        C->padre = A;
    B->padre = padre;

    A->FE = A->FE - 1 - (B->FE > 0 ? B->FE : 0);
    B->FE = B->FE - 1 + (A->FE < 0 ? A->FE : 0);
}

void avl_RDD(AVL *r, AVL nodo) {
    if (r == NULL || nodo == NULL || nodo->izq == NULL || nodo->izq->der == NULL) {
        return;
    }

    AVL A = nodo;
    AVL B = A->izq;

    avl_RSI(r, B);
    avl_RSD(r, A);
}

void avl_RDI(AVL *r, AVL nodo) {
    if (r == NULL || nodo == NULL || nodo->der == NULL || nodo->der->izq == NULL) {
        return;
    }

    AVL A = nodo;
    AVL B = A->der;

    avl_RSD(r, B);
    avl_RSI(r, A);
}

/**
 * @brief Llama al TAD de insercion void sin convertirlo en un estado de error.
 * @param arbol Referencia prestada a la raiz del llamador.
 * @note La reserva nueva queda propiedad del llamador; el TAD no imprime ni libera.
 */
void ejecutar_insercion(AVL *arbol) {
    avl_insertar(arbol, 10);
}
